import numpy as np
from scipy.optimize import minimize

def objective(vars):
    x, y, z, w = vars
    return (x**4 + y**4 + z**4 + w**4) - 8*(x**3 + y**3 + z**3 + w**3)

def constraint1(vars):
    return sum(vars) - 12

def constraint2(vars):
    return sum(v**2 for v in vars) - 48

cons = [{'type': 'eq', 'fun': constraint1},
        {'type': 'eq', 'fun': constraint2}]

# Random starting points
import random
best_f = float('inf')
for _ in range(1000):
    start = [random.uniform(-10, 20) for _ in range(4)]
    res = minimize(objective, start, constraints=cons)
    if res.success:
        if res.fun < best_f:
            best_f = res.fun

print(best_f)
